begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000005236','economic-recon@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005236","role":"authenticated"}';
select set_config('test.tenant',create_tenant_with_locale('Economic reconciliation','economic-recon',gen_random_uuid(),'dk')::text,true);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),(current_store_policy(current_setting('test.tenant')::uuid)->>'id')::uuid,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeStoreOwned":"store_full"}');
select set_config('test.purchase',register_purchase(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic item',1000,'Synthetic receipt',false)::text,true);
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'purchase',current_setting('test.purchase')::uuid,null,10000);
select record_sale(current_setting('test.tenant')::uuid,gen_random_uuid(),'manual','economic-recon-sale','2026-10-01T10:00:00Z','DKK',jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item'),'priceOre',10000)));
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','no_close','real sale starts without a close');
select set_config('test.close',gen_random_uuid()::text,true);
select generate_day_close(current_setting('test.tenant')::uuid,current_setting('test.close')::uuid,'2026-10-01');
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','not_exported','real close awaits destination export');
select store_economic_connection(current_setting('test.tenant')::uuid,123456,'Synthetic','','DKK','{"iv":"a","tag":"b","data":"c"}');
select set_config('test.map',gen_random_uuid()::text,true);
select publish_economic_map(current_setting('test.tenant')::uuid,current_setting('test.map')::uuid,null,123456,1,
 '{"grossOre":{"account":"10000","side":"debit","vatCode":"Z0"},"mode:store_full:netOre":{"account":"30000","side":"credit","vatCode":"Z0"},"mode:store_full:vatOre":{"account":"40000","side":"credit","vatCode":"Z0"},"commissionOre":{"excludeReason":"Store-owned proceeds are posted using the net and VAT mode totals"},"commissionVatOre":{"excludeReason":"VAT is posted using the mode VAT total"}}');
select set_config('test.export',export_economic_day_close(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.close')::uuid)::text,true);
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','not_sent','destination export awaits send');
select is(accounting_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','not_exported','SIE/Fortnox facts remain separate');
select is((select sum((line->>'amountOre')::bigint) from economic_exports e,jsonb_array_elements(e.voucher) line where e.id=current_setting('test.export')::uuid and line->>'account'='40000'),2000::numeric,'frozen VAT is posted explicitly in integer ore');
select set_config('test.send',gen_random_uuid()::text,true);
select begin_economic_send(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,current_setting('test.export')::uuid);
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','send_pending','pending send shown');
select complete_economic_send(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,'failed',null,'ECONOMIC_OUTCOME_UNKNOWN','ECONOMIC_CONNECTION_FAILED',null);
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','send_failed','held send shown');
select confirm_economic_send(current_setting('test.tenant')::uuid,current_setting('test.send')::uuid,1,42,'All synthetic lines verified');
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','sent','append-only confirmation completes reconciliation');
select is((select status from economic_sends where id=current_setting('test.send')::uuid),'failed','confirmation preserves the original outcome');
select publish_economic_map(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.map')::uuid,123456,1,current_economic_map(current_setting('test.tenant')::uuid)->'map');
select is(economic_reconciliation(current_setting('test.tenant')::uuid,'2026-10-01','2026-10-01')->'days'->0->>'status','export_outdated','new map leaves older export visible as outdated');
select throws_like($$select economic_reconciliation(current_setting('test.tenant')::uuid,'2020-01-01','2026-10-01')$$,'%INVALID_INPUT%','reconciliation period bounded');
reset role;
select * from finish();
rollback;
